44	  const auto cmd = access_register_command(regno_csr(mstatus), AarSize::Bits64,
45	                                           /*write=*/false);
46	  CHECK(((cmd >> 16) & 0x1) == 0u);
47	  CHECK((cmd & 0xffff)      == mstatus);
48	  CHECK(((cmd >> 17) & 0x1) == 1u);                 // transfer always 1
49	}
