51	TEST_CASE("32-bit aarsize encodes as 2")
52	{
53	  const auto cmd =
54	    access_register_command(regno_gpr(1), AarSize::Bits32, /*write=*/true);
55	  CHECK(((cmd >> 20) & 0x7) == 2u);
56	}
