59	{
60	  const auto with_post = access_register_command(
61	    regno_gpr(0), AarSize::Bits64, /*write=*/false, /*postexec=*/true);
62	  const auto without = access_register_command(
63	    regno_gpr(0), AarSize::Bits64, /*write=*/false, /*postexec=*/false);
64	  CHECK(((with_post >> 18) & 0x1) == 1u);
65	  CHECK(((without   >> 18) & 0x1) == 0u);
